using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

/// <summary>
/// Encodes the approved scenario from
/// .copilot-tracking/skraft-plans/checkout-pricing/features/loyalty-discount.feature:
/// "Gold customer receives the approved discount".
/// </summary>
public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithHundredSubtotalPaysNinetyFive()
    {
        var checkout = new CheckoutCalculator();

        var payableTotal = checkout.CalculatePayableTotal(CustomerTier.Gold, subtotal: 100.00m);

        Assert.Equal(95.00m, payableTotal);
    }
}

